using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

public static class TestDbContextFactory
{
    public static SchoolContext Create(string dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;

        var context = new SchoolContext(options);
        context.Database.EnsureCreated();
        return context;
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests
{
    private SchoolContext CreateContextWithStudents()
    {
        var context = TestDbContextFactory.Create();
        context.Students.AddRange(
            new Student { ID = 1, LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = DateTime.Parse("2020-09-01") },
            new Student { ID = 2, LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = DateTime.Parse("2021-09-01") },
            new Student { ID = 3, LastName = "Barzdukas", FirstMidName = "Arturo", EnrollmentDate = DateTime.Parse("2022-09-01") }
        );
        context.SaveChanges();
        return context;
    }

    [Fact]
    public void Index_ReturnsViewResult_WithPaginatedList()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Index_FiltersBySearchString()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, null, "Alexander", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SortsByNameDescending()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Barzdukas", model[0].LastName);
    }

    [Fact]
    public void Index_SortsByDateAscending()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SortsByDateDescending()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Barzdukas", model[0].LastName);
    }

    [Fact]
    public void Index_SearchStringResetsPageToOne()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, null, "Alonso", 5) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_UsesCurrentFilterWhenSearchStringIsNull()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Index(null, "Alexander", null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Details_ReturnsNotFoundForNullId()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Details(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Details_ReturnsViewResultWithStudent()
    {
        var context = CreateContextWithStudents();
        // Add enrollment data for the Include
        context.Courses.Add(new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 });
        context.Departments.Add(new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = DateTime.Now });
        context.SaveChanges();
        context.Enrollments.Add(new Enrollment { EnrollmentID = 1, CourseID = 1050, StudentID = 1, Grade = Grade.A });
        context.SaveChanges();

        var controller = new StudentsController(context);

        var result = controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", model.LastName);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultDate()
    {
        var context = TestDbContextFactory.Create();
        var controller = new StudentsController(context);

        var result = controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidModel_RedirectsToIndex()
    {
        var context = TestDbContextFactory.Create();
        var controller = new StudentsController(context);
        var student = new Student
        {
            LastName = "TestLast",
            FirstMidName = "TestFirst",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Single(context.Students);
    }

    [Fact]
    public void Create_Post_InvalidDate_ReturnsView()
    {
        var context = TestDbContextFactory.Create();
        var controller = new StudentsController(context);
        var student = new Student
        {
            LastName = "TestLast",
            FirstMidName = "TestFirst",
            EnrollmentDate = DateTime.MinValue
        };

        var result = controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        var context = TestDbContextFactory.Create();
        var controller = new StudentsController(context);
        controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            LastName = "",
            FirstMidName = "TestFirst",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = controller.Create(student) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_ReturnsNotFoundForNullId()
    {
        var context = CreateContextWithStudents();
        var controller = new StudentsController(context);

        var result = controller.Edit(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
