using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests
{
    [Fact]
    public void SendNotification_EnqueuesNotification()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "TestUser");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("TestUser", notification.CreatedBy);
        Assert.Contains("John Doe", notification.Message);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityId()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "42", EntityOperation.UPDATE, "Admin");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
    }

    [Fact]
    public void SendNotification_CreateOperation_GeneratesCorrectMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Course", "101", "Math 101", EntityOperation.CREATE);

        var notification = service.ReceiveNotification();
        Assert.Equal("New Course 'Math 101' has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_UpdateOperation_GeneratesCorrectMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Course", "101", "Math 101", EntityOperation.UPDATE);

        var notification = service.ReceiveNotification();
        Assert.Equal("Course 'Math 101' has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Course", "101", "Math 101", EntityOperation.DELETE);

        var notification = service.ReceiveNotification();
        Assert.Equal("Course 'Math 101' has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_DefaultUserIsSystem()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        var notification = service.ReceiveNotification();
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_ReturnsNull_WhenQueueIsEmpty()
    {
        var service = new NotificationService();

        var notification = service.ReceiveNotification();

        Assert.Null(notification);
    }

    [Fact]
    public void ReceiveNotification_DequesInFifoOrder()
    {
        var service = new NotificationService();
        service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
        service.SendNotification("Student", "2", "Second", EntityOperation.CREATE);

        var first = service.ReceiveNotification();
        var second = service.ReceiveNotification();

        Assert.Contains("First", first.Message);
        Assert.Contains("Second", second.Message);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var service = new NotificationService();

        var ex = Record.Exception(() => service.MarkAsRead(999));

        Assert.Null(ex);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();

        var ex = Record.Exception(() => service.Dispose());

        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_SetsCreatedAt()
    {
        var service = new NotificationService();
        var before = DateTime.Now;

        service.SendNotification("Test", "1", "Entity", EntityOperation.CREATE);

        var notification = service.ReceiveNotification();
        Assert.True(notification.CreatedAt >= before);
        Assert.True(notification.CreatedAt <= DateTime.Now);
    }
}

