using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using Microsoft.EntityFrameworkCore;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests
{
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
    }

    private SchoolContext CreateContextWithCourses()
    {
        var context = TestDbContextFactory.Create();
        context.Departments.Add(new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = DateTime.Now });
        context.SaveChanges();
        context.Courses.AddRange(
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 4041, Title = "Macroeconomics", Credits = 3, DepartmentID = 1 }
        );
        context.SaveChanges();
        return context;
    }

    [Fact]
    public void Index_ReturnsViewWithCourses()
    {
        var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _mockEnv.Object, _mockLogger.Object);

        var result = controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(3, model.Count);
    }

    [Fact]
    public void Details_ReturnsNotFoundForNullId()
    {
        var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _mockEnv.Object, _mockLogger.Object);

        var result = controller.Details(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Details_ReturnsViewForValidId()
    {
        var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _mockEnv.Object, _mockLogger.Object);

        var result = controller.Details(1050) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", model.Title);
    }

    [Fact]
    public void Create_Get_ReturnsView()
    {
        var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _mockEnv.Object, _mockLogger.Object);

        var result = controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.IsType<Course>(result.Model);
    }

    [Fact]
    public void Create_Post_ValidModel_RedirectsToIndex()
    {
        var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _mockEnv.Object, _mockLogger.Object);
        var course = new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = 1 };

        var result = controller.Create(course, null) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(4, context.Courses.Count());
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _mockEnv.Object, _mockLogger.Object);
        controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 2021, Title = "", Credits = 3, DepartmentID = 1 };

        var result = controller.Create(course, null) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Create_Post_WithInvalidFileExtension_ReturnsView()
    {
        var context = CreateContextWithCourses();
        var controller = new CoursesController(context, _mockEnv.Object, _mockLogger.Object);
        var course = new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = 1 };

        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("test.txt");
        mockFile.Setup(f => f.Length).Returns(1024);

        var result = controller.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
