using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class DepartmentsControllerTests
{
    private SchoolContext CreateContextWithDepartments()
    {
        var context = TestDbContextFactory.Create();
        context.Instructors.Add(new Instructor { ID = 1, LastName = "Fakhouri", FirstMidName = "Fadi", HireDate = DateTime.Parse("2002-07-06") });
        context.SaveChanges();
        context.Departments.AddRange(
            new Department { DepartmentID = 1, Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = 1 },
