            new Department { DepartmentID = 3, Name = "Engineering", Budget = 150000, StartDate = DateTime.Parse("2007-09-01") }
        );
        context.SaveChanges();
        return context;
    }

    [Fact]
    public void Index_ReturnsViewWithDepartments()
    {
        var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Department>>(result.Model);
        Assert.Equal(3, model.Count);
