        if (tracked != null) context.Entry(tracked).State = EntityState.Detached;

        var department = new Department
        {
            DepartmentID = 1,
            Name = "English Updated",
            Budget = 400000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = 1
        };

        var result = controller.Edit(department) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidModel_ReturnsView()
    {
        var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);
        controller.ModelState.AddModelError("Name", "Required");
        var department = new Department { DepartmentID = 1, Name = "", Budget = 0, StartDate = DateTime.Now };

        var result = controller.Edit(department) as ViewResult;

        Assert.NotNull(result);
    }

