    public void Delete_Get_ReturnsNotFoundForNullId()
    {
        var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Delete(null);

        Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
    }

    [Fact]
    public void Delete_Get_ReturnsNotFoundForInvalidId()
    {
        var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Delete(999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ReturnsViewForValidId()
    {
        var context = CreateContextWithDepartments();
        var controller = new DepartmentsController(context);

        var result = controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal("English", model.Name);
    }

    [Fact]
    public void DeleteConfirmed_RemovesDepartmentAndRedirects()
    {
        var context = CreateContextWithDepartments();
