using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests
{
    private SchoolContext CreateContextWithInstructors()
    {
        var context = TestDbContextFactory.Create();
        context.Departments.Add(new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = DateTime.Now });
        context.SaveChanges();
        context.Courses.AddRange(
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 1 }
        );
        context.SaveChanges();

        var instructor1 = new Instructor { ID = 1, LastName = "Fakhouri", FirstMidName = "Fadi", HireDate = DateTime.Parse("2002-07-06") };
        var instructor2 = new Instructor { ID = 2, LastName = "Harui", FirstMidName = "Roger", HireDate = DateTime.Parse("1998-07-01") };
        context.Instructors.AddRange(instructor1, instructor2);
        context.SaveChanges();

        context.OfficeAssignments.Add(new OfficeAssignment { InstructorID = 1, Location = "Smith 17" });
        context.CourseAssignments.Add(new CourseAssignment { InstructorID = 1, CourseID = 1050 });
        context.SaveChanges();

        return context;
    }

    [Fact]
    public void Index_ReturnsViewWithInstructorData()
    {
        var context = CreateContextWithInstructors();
        var controller = new InstructorsController(context);

        var result = controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_ShowsCourses()
    {
