using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        var context = TestDbContextFactory.Create();
        var student = new Student { LastName = "Smith", FirstMidName = "John", EnrollmentDate = DateTime.Parse("2023-09-01") };

        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.First();
        Assert.Equal("Smith", retrieved.LastName);
        Assert.Equal("John", retrieved.FirstMidName);
    }

    [Fact]
    public void CanAddAndRetrieveInstructor()
    {
        var context = TestDbContextFactory.Create();
        var instructor = new Instructor { LastName = "Jones", FirstMidName = "Amy", HireDate = DateTime.Parse("2020-01-15") };

        context.Instructors.Add(instructor);
        context.SaveChanges();

        var retrieved = context.Instructors.First();
        Assert.Equal("Jones", retrieved.LastName);
    }

    [Fact]
    public void CanAddAndRetrieveCourse()
    {
        var context = TestDbContextFactory.Create();
        context.Departments.Add(new Department { DepartmentID = 1, Name = "CS", Budget = 50000, StartDate = DateTime.Now });
        context.SaveChanges();
        var course = new Course { CourseID = 1001, Title = "Algorithms", Credits = 4, DepartmentID = 1 };

        context.Courses.Add(course);
        context.SaveChanges();

        var retrieved = context.Courses.First();
        Assert.Equal("Algorithms", retrieved.Title);
        Assert.Equal(4, retrieved.Credits);
    }

    [Fact]
    public void CanAddAndRetrieveDepartment()
    {
        var context = TestDbContextFactory.Create();
        var department = new Department { Name = "Physics", Budget = 250000, StartDate = DateTime.Parse("2020-09-01") };

        context.Departments.Add(department);
        context.SaveChanges();

        var retrieved = context.Departments.First();
        Assert.Equal("Physics", retrieved.Name);
        Assert.Equal(250000, retrieved.Budget);
    }

    [Fact]
    public void CanAddEnrollment_WithStudentAndCourse()
    {
        var context = TestDbContextFactory.Create();
        context.Departments.Add(new Department { DepartmentID = 1, Name = "CS", Budget = 50000, StartDate = DateTime.Now });
        context.SaveChanges();
        var student = new Student { LastName = "Test", FirstMidName = "Student", EnrollmentDate = DateTime.Now };
        var course = new Course { CourseID = 2001, Title = "DB Systems", Credits = 3, DepartmentID = 1 };
        context.Students.Add(student);
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment { StudentID = student.ID, CourseID = 2001, Grade = Grade.B };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var retrieved = context.Enrollments.Include(e => e.Student).Include(e => e.Course).First();
        Assert.Equal("Test", retrieved.Student.LastName);
        Assert.Equal("DB Systems", retrieved.Course.Title);
        Assert.Equal(Grade.B, retrieved.Grade);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        var context = TestDbContextFactory.Create();
        context.Departments.Add(new Department { DepartmentID = 1, Name = "CS", Budget = 50000, StartDate = DateTime.Now });
        context.SaveChanges();
        context.Instructors.Add(new Instructor { ID = 10, LastName = "Prof", FirstMidName = "Test", HireDate = DateTime.Now });
        context.Courses.Add(new Course { CourseID = 3001, Title = "Networks", Credits = 3, DepartmentID = 1 });
        context.SaveChanges();

        context.CourseAssignments.Add(new CourseAssignment { InstructorID = 10, CourseID = 3001 });
        context.SaveChanges();

        var assignment = context.CourseAssignments.First();
        Assert.Equal(10, assignment.InstructorID);
        Assert.Equal(3001, assignment.CourseID);
    }

    [Fact]
    public void OfficeAssignment_LinkedToInstructor()
    {
        var context = TestDbContextFactory.Create();
        var instructor = new Instructor { ID = 20, LastName = "Office", FirstMidName = "Test", HireDate = DateTime.Now };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        context.OfficeAssignments.Add(new OfficeAssignment { InstructorID = 20, Location = "Room 101" });
        context.SaveChanges();

        var office = context.OfficeAssignments.Include(o => o.Instructor).First();
        Assert.Equal("Room 101", office.Location);
        Assert.Equal("Office", office.Instructor.LastName);
    }

    [Fact]
    public void Person_FullName_ReturnsConcatenation()
    {
        var student = new Student { LastName = "Doe", FirstMidName = "Jane", EnrollmentDate = DateTime.Now };

        Assert.Equal("Doe, Jane", student.FullName);
    }

    [Fact]
    public void Notification_CanBeAddedToContext()
    {
        var context = TestDbContextFactory.Create();
        var notification = new Notification
        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "Test notification",
            CreatedAt = DateTime.Now,
            CreatedBy = "System",
            IsRead = false
        };

        context.Notifications.Add(notification);
        context.SaveChanges();

        var retrieved = context.Notifications.First();
        Assert.Equal("Test notification", retrieved.Message);
        Assert.False(retrieved.IsRead);
    }

    [Fact]
    public void Department_CanHaveAdministrator()
    {
        var context = TestDbContextFactory.Create();
        var instructor = new Instructor { ID = 30, LastName = "Admin", FirstMidName = "Dept", HireDate = DateTime.Now };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var department = new Department { Name = "Science", Budget = 100000, StartDate = DateTime.Now, InstructorID = 30 };
        context.Departments.Add(department);
        context.SaveChanges();

        var retrieved = context.Departments.Include(d => d.Administrator).First();
        Assert.NotNull(retrieved.Administrator);
        Assert.Equal("Admin", retrieved.Administrator.LastName);
    }
}

