using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models;

public class PaginatedListTests
{
    [Fact]
    public void Create_ReturnsCorrectPageOfItems()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var page = PaginatedList<int>.Create(items, 1, 10);

        Assert.Equal(10, page.Count);
        Assert.Equal(1, page.PageIndex);
        Assert.Equal(3, page.TotalPages);
    }

    [Fact]
    public void HasPreviousPage_FalseOnFirstPage()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var page = PaginatedList<int>.Create(items, 1, 10);

        Assert.False(page.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_TrueOnSecondPage()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var page = PaginatedList<int>.Create(items, 2, 10);

        Assert.True(page.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_TrueOnFirstPage()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var page = PaginatedList<int>.Create(items, 1, 10);

        Assert.True(page.HasNextPage);
    }

    [Fact]
    public void HasNextPage_FalseOnLastPage()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var page = PaginatedList<int>.Create(items, 3, 10);

        Assert.False(page.HasNextPage);
    }

    [Fact]
    public void Create_LastPage_HasRemainingItems()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var page = PaginatedList<int>.Create(items, 3, 10);

        Assert.Equal(5, page.Count);
    }

    [Fact]
    public void Create_SinglePage_NoNavigation()
    {
        var items = Enumerable.Range(1, 5).AsQueryable();

        var page = PaginatedList<int>.Create(items, 1, 10);

        Assert.False(page.HasPreviousPage);
        Assert.False(page.HasNextPage);
        Assert.Equal(1, page.TotalPages);
    }

    [Fact]
    public void Constructor_SetsProperties()
    {
        var list = new List<string> { "a", "b", "c" };

        var page = new PaginatedList<string>(list, 10, 2, 3);

        Assert.Equal(2, page.PageIndex);
        Assert.Equal(4, page.TotalPages);
        Assert.Equal(3, page.Count);
    }
}

