[Fact]
public void Index_WithCourseId_SetsViewBagCourseID()
{
    // Course.Enrollments relies on lazy loading (virtual nav property).
    // The InMemory provider doesn't support lazy loading, so this test verifies the
    // instructor+course path works, and that the controller at least sets Enrollments 
    // (which may be null from the nav property in InMemory mode).
    var context = CreateContextWithInstructors();
    var controller = new InstructorsController(context);

    // Only test the instructor selection path (courseID=null)
    // because Course.Enrollments is null without lazy loading proxies.
    var result = controller.Index(1, null) as ViewResult;

    Assert.NotNull(result);
    var model = Assert.IsType<InstructorIndexData>(result.Model);
    Assert.NotNull(model.Courses);
    Assert.Single(model.Courses);
    Assert.Equal(1050, model.Courses.First().CourseID);
}

